def get_rules_by_category(category):
    return [r for r in SNORT_RULES if r["category"] == category]

def get_rules_by_mitre(technique_id):
    return [r for r in SNORT_RULES if r["mitre"] == technique_id]

def get_rules_by_severity(severity):
    return [r for r in SNORT_RULES if r["severity"] == severity]

def export_rules(rules=None, fmt="snort"):
    if rules is None:
        rules = SNORT_RULES
    return "\n".join(r["rule"] for r in rules)

