    rules = get_rules_by_category(cat) if cat else SNORT_RULES
    for r in rules:
        print(f"  [{r['severity'].upper():8s}] SID:{r['sid']}  {r['msg']}  ({r['mitre']})")
    print(f"\n  Total: {len(rules)} rules" + (f" in category '{cat}'" if cat else ""))
